#include "wiegand.h"

/* ---- writing ------------------------------------------------------------- */

/* Collects text and hands it to the sink a block at a time, so a save is a
 * handful of storage calls and not one per bit. */
typedef struct {
    WiegandFileSink sink;
    void* context;
    char buffer[160];
    size_t used;
    bool ok;
} Writer;

static void writer_flush(Writer* w) {
    if(w->used > 0 && w->ok) {
        if(!w->sink(w->context, w->buffer, w->used)) w->ok = false;
    }
    w->used = 0;
}

static void writer_str(Writer* w, const char* text) {
    while(*text) {
        if(w->used == sizeof(w->buffer)) writer_flush(w);
        w->buffer[w->used++] = *text++;
    }
}

bool wiegand_file_write(WiegandFileSink sink, void* context) {
    int n = bit_count;
    char text[WIEGAND_BINARY_TEXT_SIZE];
    Writer w = {.sink = sink, .context = context, .used = 0, .ok = true};

    snprintf(
        text,
        sizeof(text),
        "Filetype: Flipper Wiegand Key File\nVersion: 1\nProtocol: RAW\nBits: %d\n",
        n);
    writer_str(&w, text);
    snprintf(
        text,
        sizeof(text),
        "Truncated_Bits: %lu\nGlitches: %lu\n",
        (unsigned long)overflow_bits,
        (unsigned long)glitch_count);
    writer_str(&w, text);

    writer_str(&w, "RAW_Data: ");
    for(int i = 0; i < n; i++) {
        snprintf(
            text,
            sizeof(text),
            "D%d %lu %lu ",
            data[i] ? 1 : 0,
            (unsigned long)(data_fall[i] - data_fall[0]),
            (unsigned long)(data_rise[i] - data_fall[0]));
        writer_str(&w, text);
    }
    writer_str(&w, "\n");

    writer_str(&w, "PACS_Binary: ");
    wiegand_format_binary_plain(data, n, text, sizeof(text));
    writer_str(&w, text);

    writer_str(&w, "\nHex_Right_Justified: ");
    wiegand_format_hex(data, n, false, text, sizeof(text));
    writer_str(&w, text);

    writer_str(&w, "\nHex_Left_Justified: ");
    wiegand_format_hex(data, n, true, text, sizeof(text));
    writer_str(&w, text);
    writer_str(&w, "\n");

    writer_flush(&w);
    return w.ok;
}

/* ---- reading ------------------------------------------------------------- */

static bool starts_with(const char* line, const char* prefix) {
    return strncmp(line, prefix, strlen(prefix)) == 0;
}

static bool is_digit(char ch) {
    return ch >= '0' && ch <= '9';
}

/* Reads an unsigned decimal number at *pos and leaves *pos on the first
 * character after it. */
static uint32_t parse_number(const char** pos) {
    uint32_t value = 0;
    while(is_digit(**pos)) {
        value = value * 10 + (uint32_t)(**pos - '0');
        (*pos)++;
    }
    return value;
}

static void skip_spaces(const char** pos) {
    while(**pos == ' ') (*pos)++;
}

/* "D0 0 2243 D1 124823 127090 ..." */
static void parse_raw_data(const char* pos) {
    int n = 0;

    while(*pos) {
        if(*pos != 'D') {
            pos++;
            continue;
        }
        pos++;
        if(!*pos) break;
        bool value = *pos == '1';
        pos++;
        skip_spaces(&pos);
        uint32_t fall = parse_number(&pos);
        skip_spaces(&pos);
        uint32_t rise = parse_number(&pos);

        if(n >= MAX_BITS) {
            overflow_bits++;
            continue;
        }
        data[n] = value;
        data_fall[n] = fall;
        data_rise[n] = rise;
        n++;
    }
    bit_count = n;
}

void wiegand_file_load_begin(WiegandFileLoad* load) {
    bit_count = 0;
    overflow_bits = 0;
    glitch_count = 0;
    load->declared_bits = -1;
    load->has_raw = false;
}

bool wiegand_file_load_line(WiegandFileLoad* load, const char* line) {
    static const char bits_key[] = "Bits: ";
    static const char truncated_key[] = "Truncated_Bits: ";
    static const char glitches_key[] = "Glitches: ";
    static const char raw_key[] = "RAW_Data: ";
    const char* pos;

    if(starts_with(line, bits_key)) {
        pos = line + strlen(bits_key);
        load->declared_bits = (int)parse_number(&pos);
    } else if(starts_with(line, truncated_key)) {
        pos = line + strlen(truncated_key);
        overflow_bits = parse_number(&pos);
    } else if(starts_with(line, glitches_key)) {
        pos = line + strlen(glitches_key);
        glitch_count = parse_number(&pos);
    } else if(starts_with(line, raw_key)) {
        parse_raw_data(line + strlen(raw_key));
        load->has_raw = true;
        return true;
    }
    return false;
}

bool wiegand_file_load_bits_match(const WiegandFileLoad* load) {
    return load->declared_bits < 0 || load->declared_bits == bit_count;
}
